    await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("7.20");
    await expect(pg_vic.getByTestId("period-row-P1").getByTestId("period-due-total")).toHaveText("7.20");
    await expect(pg_vic.getByTestId("period-row-P1").getByTestId("period-closed")).toHaveText("no");
    expect(await ui.periodAction(pg_vic, "P1", "close")).toBe(true);
    await ui.setSetting(pg_vic, "floor", "5.00");
    expect(await ui.statement(pg_vic, p_ada)).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("9.20");
